        self,
        api_key: [REDACTED_SECRET] = None,
        base_url: str = \"api.openai.com\",
        endpoint: str = \"/v1/responses\",
        timeout: int = 30,
    ) -> None:
        self.api_key = api_key or os.getenv(\"OPENAI_API_KEY\")
        if not self.api_key:
            raise ValueError(
                \"API key must be provided or set via OPENAI_API_KEY environment variable\"
            )
        self.base_url = base_url
        self.endpoint = endpoint
        self.timeout = timeout

    def _make_request(
        self,
        method: str,
        body: Optional[str] = None,
        headers: Optional[Dict[str, str]] = None,
    ) -> http.client.HTTPResponse:
        conn = http.client.HTTPSConnection(self.base_url, timeout=self.timeout)
        try:
            default_headers = {
                \"Authorization\": f\"Bearer {self.api_key}\",
                \"Content-Type\": \"application/json\",
                \"User-Agent\": \"openai-client-stdlib/1.0\",
            }
            if headers:
                default_headers.update(headers)
            conn.request(method, self.endpoint, body=body, headers=default_headers)
            return conn.getresponse()
        except Exception:
            conn.close()
            raise

    def send_prompt(
        self,
        prompt: str,
        model: str = \"gpt-4\",
        max_tokens: int = 150,
        temperature: float = 0.7,
        stream: bool = True,
    ) -> Union[str, Generator[str, None, None]]:
        \"\"\"
        Send a text prompt to the OpenAI Responses API.

        Args:
            prompt: The user prompt text.
            model: The model to use (default: gpt-4).
            max_tokens: Maximum number of tokens to generate.
            temperature: Sampling temperature.
            stream: If True, stream response chunks; otherwise return full response.

        Returns:
            If stream=True, a generator yielding response string chunks.
            If stream=False, the complete response string.
        \"\"\"
        payload = {
            \"model\": model,
            \"messages\": [{\"role\": \"user\", \"content\": prompt}],
            \"max_tokens\": max_tokens,
            \"temperature\": temperature,
        }
        body = json.dumps(payload)
        response = self._make_request(\"POST\", body=body)

        if response.status "'!= 200:
            raise Exception(
                f"API request failed with status {response.status}: {response.read().decode()}"
            )

        if stream:
            def _stream() -> Generator[str, None, None]:
                try:
