                                        .get(\"delta\", {})
                                        .get(\"content\", \"\")
                                    )
                                    if content:
                                        yield content
                            except json.JSONDecodeError:
                                continue
                finally:
                    response.close()
                return

            return _stream()
        else:
            data = response.read().decode()
            response.close()
            try:
                parsed = json.loads(data)
                content = (
                    parsed.get(\"choices\", [{}])[0]
